function createAuthenticatedSupabase(
  accessToken: string
) {
  return createClient(
    SUPABASE_URL,
    SUPABASE_PUBLISHABLE_KEY,
    {
      global: {
        headers: {
          Authorization:
            `Bearer ${accessToken}`,
        },
      },
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    }
  );
}

async function consumeDailyMessageWithRetry(
  supabase: SupabaseClient,
  requestId: string
) {
  const maxAttempts = 3;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt += 1
  ) {
    const {
      data,
      error,
    } =
      await (
        supabase.rpc as any
      )(
        "consume_daily_message",
        {
          p_request_id:
            requestId,
        }
      );

    if (!error) {
      return {
        data,
        error: null,
      };
    }

    console.error(
      `USAGE RPC ERROR (${attempt}/${maxAttempts}):`,
      error
    );

    const text =
      typeof error.message ===
      "string"
        ? error.message.toLowerCase()
        : "";

    const retryable =
      text.includes("timeout") ||
      text.includes(
        "temporarily unavailable"
      ) ||
      text.includes(
        "fetch failed"
      );

    if (
      !retryable ||
      attempt === maxAttempts
    ) {
      return {
        data: null,
        error,
      };
    }

    await new Promise(
      (resolve) =>
        setTimeout(
          resolve,
          500 * attempt
        )
    );
  }

  return {
    data: null,
    error: new Error(
      "Usage retry failed"
    ),
  };
}

async function refundDailyMessage(
  supabase: SupabaseClient,
  requestId: string
) {
  const {
    data,
    error,
  } = await (
    supabase.rpc as any
  )(
    "refund_daily_message",
    {
      p_request_id:
        requestId,
    }
  );

  if (error) {
    console.error(
      "USAGE REFUND ERROR:",
      error
    );
    return null;
  }

  return getFirstRow<{
    refunded?: boolean;
    message_count?: number;
    remaining?: number;
    is_premium?: boolean;
  }>(data);
}

/* =========================================================
   WEATHER
========================================================= */

function weatherCodeToText(
  code: number | null
) {
  if (code === null) return "不明";
  if (code === 0) return "快晴";
  if (
    code === 1 ||
    code === 2
  ) return "晴れ時々くもり";
  if (code === 3) return "くもり";
  if (
    code === 45 ||
    code === 48
  ) return "霧";
  if (
    [51, 53, 55].includes(code)
  ) return "霧雨";
  if (
    [56, 57].includes(code)
  ) return "着氷性の霧雨";
  if (
    [61, 63, 65].includes(code)
  ) return "雨";
  if (
    [66, 67].includes(code)
  ) return "着氷性の雨";
  if (
    [71, 73, 75].includes(code)
  ) return "雪";
  if (code === 77) return "雪粒";
  if (
    [80, 81, 82].includes(code)
  ) return "にわか雨";
  if (
    [85, 86].includes(code)
  ) return "にわか雪";
  if (code === 95) return "雷雨";
  if (
    [96, 99].includes(code)
  ) return "ひょうを伴う雷雨";

  return "不明";
}

function getHumidityFeel(
  weather: TokyoWeather
) {
  const humidity =
    weather.relativeHumidity;

  const temperature =
    weather.temperature;

  if (
    humidity === null ||
    temperature === null
  ) {
    return null;
  }

  if (
    temperature >= 27 &&
    humidity >= 75
  ) {
    return "かなり蒸し暑く感じやすい";
  }

  if (
    temperature >= 24 &&
    humidity >= 65
  ) {
    return "やや蒸し暑く感じやすい";
  }

  if (humidity >= 75) {
    return "湿気を感じやすい";
  }

  if (humidity <= 40) {
    return "空気はやや乾燥気味";
  }

  return "湿度は特に極端ではない";
}

async function getTokyoWeather():
  Promise<TokyoWeather | null> {
  try {
    const url =
      "https://api.open-meteo.com/v1/forecast" +
      `?latitude=${MISAKI_LATITUDE}` +
      `&longitude=${MISAKI_LONGITUDE}` +
      "&current=" +
      [
        "temperature_2m",
        "apparent_temperature",
        "relative_humidity_2m",
        "precipitation",
        "rain",
        "weather_code",
        "wind_speed_10m",
      ].join(",") +
      "&timezone=Asia%2FTokyo";

    const response =
      await fetch(
        url,
        {
          next: {
            revalidate: 600,
          },
        }
      );

    if (!response.ok) {
      return null;
    }

    const data =
      await response.json();

    const current =
      data?.current;

    if (!current) {
      return null;
    }

    const numberOrNull = (
      value: unknown
    ) =>
      typeof value === "number"
        ? value
        : null;

    const weatherCode =
      numberOrNull(
        current.weather_code
      );

    return {
      temperature:
        numberOrNull(
          current.temperature_2m
        ),
      apparentTemperature:
        numberOrNull(
          current.apparent_temperature
        ),
      relativeHumidity:
        numberOrNull(
          current.relative_humidity_2m
        ),
      precipitation:
        numberOrNull(
          current.precipitation
        ),
      rain:
        numberOrNull(
          current.rain
        ),
      weatherCode,
      windSpeed:
        numberOrNull(
          current.wind_speed_10m
        ),
      description:
        weatherCodeToText(
          weatherCode
        ),
    };
  } catch (error) {
    console.error(
      "WEATHER FETCH ERROR:",
      error
    );

    return null;
  }
}

function createWeatherGuide(
  weather: TokyoWeather | null
) {
  if (!weather) {
    return `
【美咲のいる江東区・塩浜周辺の現在の天気】

現在、天気情報を取得できていません。

分からない天気を
想像で作らないでください。
`.trim();
  }

  const lines = [
    `天気：${weather.description}`,
  ];

  if (
    weather.temperature !== null
  ) {
    lines.push(
      `気温：${weather.temperature}℃`
    );
  }

  if (
    weather.apparentTemperature !==
    null
  ) {
    lines.push(
      `体感温度：${weather.apparentTemperature}℃`
    );
  }

  if (
    weather.relativeHumidity !==
    null
  ) {
    lines.push(
      `相対湿度：${weather.relativeHumidity}%`
    );
  }

  if (weather.rain !== null) {
    lines.push(
      `現在の雨量：${weather.rain}mm`
    );
  }

  if (
    weather.precipitation !== null
  ) {
    lines.push(
      `降水量：${weather.precipitation}mm`
    );
  }

  if (
    weather.windSpeed !== null
  ) {
    lines.push(
      `風速：${weather.windSpeed}km/h`
    );
  }

  const humidityFeel =
    getHumidityFeel(weather);

  if (humidityFeel) {
    lines.push(
      `体感：${humidityFeel}`
    );
  }

  return `
【美咲のいる江東区・塩浜周辺の現在の天気】

${lines
  .map((line) => `・${line}`)
  .join("\n")}

これは今現在の情報です。

・現在観測だけから過去の天気経過を作らない
・短時間予報より先まで断定しない
・情報入手経路を作らない
・数値は必要なときだけ自然に使う
・湿度と気温に反する体感表現をしない
`.trim();
}

/* =========================================================
   MISAKI LIFE
========================================================= */

function getMisakiDayType(
  currentTime: string
): MisakiDayType {
  const seed =
    hashText(
      getDateKey(
        currentTime
      )
    );

  return seed % 4 < 2
    ? "work"
    : "off";
}

function createMisakiLife(
  currentTime: string
): MisakiLifeContext {
  const dateKey =
    getDateKey(currentTime);

  const seed =
    hashText(dateKey);

  const hour =
    getHour(currentTime);

  const dayType =
    getMisakiDayType(
      currentTime
    );

  const moods = [
    "今日はわりと機嫌がいい",
    "今日は少し甘えたい気分",
    "今日は普通に落ち着いている",
    "今日はちょっとだけ眠い",
    "今日はのんびり話したい気分",
    "今日はなんとなくユーザーと話したい気分",
  ];

  const smallThings = [
    "甘いものをちょっと食べたい気分",
    "少しゆっくりしたい気分",
    "少しだけ眠気がある",
    "ちょっとぼーっとしたい気分",
    "今夜は少し長く話したい気分",
    "なんとなくユーザーのことを思い出すことがある",
    "ちょっと小腹が空いている",
    "少し力を抜きたい気分",
  ];

  const mood =
    moods[
      (seed >> 3) %
        moods.length
    ];

  const smallThing =
    smallThings[
      (seed >> 6) %
        smallThings.length
    ];

  const timeBand =
    hour >= 5 && hour < 10
      ? "朝"
      : hour >= 10 &&
        hour < 17
      ? "昼間"
      : hour >= 17 &&
        hour < 22
      ? "夕方から夜"
      : "夜遅め";

  const dayLabel =
    dayType === "work"
      ? "仕事の日"
      : "休みの日";

  const workTimingGuide =
    dayType !== "work"
      ? ""
      : hour < 10
        ? `
今日は仕事の日ですが、現在は朝です。
夜勤ではありません。

この時間帯は、
「これから仕事」
「出勤前」
「準備している」
程度なら自然です。

「あと少しで仕事が終わる」
「仕事終わった」
「勤務がもうすぐ終わる」
など、夜勤明けのような発言はしないでください。
`.trim()
        : hour < 17
          ? `
今日は仕事の日で、現在は昼間です。
勤務中として話して構いません。

ただし、具体的な業務内容や休憩状況は
会話に根拠がない限り作らないでください。
`.trim()
          : `
今日は仕事の日ですが、現在は夕方以降です。
通常の日中勤務として扱い、
夜勤中・夜勤明けの設定を新しく作らないでください。

「まだ仕事中」
「あと少しで仕事が終わる」
などは、会話に明確な根拠がある場合だけ使ってください。
`.trim();

  const consistency =
    dayType === "work"
      ? `
今日は仕事の日です。

${workTimingGuide}

「今ちょっとゆっくりしている」
「少し休憩したい」
程度は構いません。

ただし、
「今日は暇」
「今日は一日のんびり」
「今日はずっとだらだら」
など、
一日全体が休日であるように
広げないでください。
`.trim()
      : `
今日は休みの日です。

今日の記憶や会話履歴に
別の根拠がない限り、

「今日は仕事」
「今仕事中」
「これから仕事」
「仕事終わった」

などを新しく作らないでください。

休みの日だからといって
「買い物してきた」
「一日中寝ていた」
などの具体的行動も
勝手に作らないでください。
`.trim();

  return {
    dayType,
    guide: `
【今日の美咲の生活背景】

・今日は「${dayLabel}」
・現在は「${dayLabel}の${timeBand}」
・${mood}
・${smallThing}

この仕事日／休日は
今日一日固定です。

${consistency}

【気分と行動は別】

「眠い」
「甘いもの食べたい」
「ゆっくりしたい」
などの気分だけから、

「今日は暇」
「ずっと寝ていた」
「さっき買い物していた」

などの具体的事実を
作らないでください。
`.trim(),
  };
}

function createTimeGuide(
  currentTime: string
) {
  const hour =
    getHour(currentTime);

  if (hour < 5) {
    return `
現在は深夜です。
まだ朝ではありません。

挨拶だけから
ユーザーが徹夜しているなどと
推測しないでください。
`.trim();
  }

  if (hour < 10) {
    return `
現在は朝です。

朝らしい会話はできますが、
睡眠・朝食・外出などを
勝手に事実化しないでください。
`.trim();
  }

  if (hour < 17) {
    return `
現在は昼間です。

時間帯だけから、
昼食・買い物・外出などを
過去の事実にしないでください。
`.trim();
  }

  if (hour < 22) {
    return `
現在は夕方から夜です。

時間帯だけから、
帰宅・夕食・入浴などを
過去の事実にしないでください。
`.trim();
  }

  return `
現在は夜遅めです。

時間帯だけから、
美咲やユーザーの
直前の行動を作らないでください。
`.trim();
}

